var S = function (v) { if (typeof v === 'string') return JSON.stringify(v); if (typeof v === 'symbol') return 'symbol'; if (v !== null && typeof v === 'object') { try { return JSON.stringify(v) } catch (e) { return 'object' } } return String(v) };
var E = function (e) { return e.constructor.name + '|' + e.name + '|' + e.message + '|' + e.code + '|' + (e instanceof Error) };
var D = function (d) { return d === undefined ? 'undefined' : [typeof d.value, d.writable, d.enumerable, d.configurable, typeof d.get, typeof d.set] };
var F = function (f) { return typeof f === 'function' ? [f.name, f.length, f.toString()] : f === undefined ? 'undefined' : typeof f };
var V = function (v) { return typeof v === 'function' ? F(v) : typeof v === 'object' && v !== null ? 'object' : typeof v === 'symbol' ? String(v) : v };
var X = function (o) { return Reflect.ownKeys(o).map(function (k) { var d = Object.getOwnPropertyDescriptor(o, k); return [String(k), 'value' in d ? V(d.value) : 'accessor', d.writable, d.enumerable, d.configurable, F(d.get), F(d.set)] }) };
var et = new EventTarget(), ev = new Event('x'), ep = Event.prototype, tp = EventTarget.prototype, log = [];
var R;
try { R = S(new MessageEvent('x', { ports: [new Error('x')] })) } catch (e) { R = E(e) }
console.error(R);

